ITEMS_OF = "CREATE FUNCTION public.project_handover_items_of(t uuid, project uuid, person uuid)\n RETURNS TABLE(kind text, subject_id uuid, task_id uuid, label text, state text)\n LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\n SELECT 'work_task'::text, c.task_id, c.task_id, v.body->>'title', c.state::text\n  FROM work_task_currents c JOIN work_task_versions v ON v.tenant_id=c.tenant_id AND v.id=c.version_id\n  WHERE c.tenant_id=t AND c.project_id=project AND c.state IN ('assigned','accepted','in_progress','submitted')\n   AND v.body->>'assignee_id'=person::text\n UNION ALL\n SELECT 'work_commitment'::text, c.version_id, c.task_id, v.body->>'title', x.state::text\n  FROM work_commitment_currents c\n  JOIN work_task_currents x ON x.tenant_id=c.tenant_id AND x.product_id=c.product_id AND x.task_id=c.task_id\n  JOIN work_task_versions v ON v.tenant_id=x.tenant_id AND v.id=x.version_id\n  LEFT JOIN work_commitment_review_currents r ON r.tenant_id=c.tenant_id AND r.product_id=c.product_id\n   AND r.commitment_id=c.version_id\n  WHERE c.tenant_id=t AND c.project_id=project AND c.promisor_id=person AND x.state<>'completed'\n   AND (r.state IS NULL OR r.state<>'fulfilled')\n UNION ALL\n SELECT 'external_wait'::text, c.wait_id, NULL::uuid, v.body->>'title', c.state::text\n  FROM external_wait_currents c JOIN external_wait_versions v ON v.tenant_id=c.tenant_id AND v.id=c.version_id\n  WHERE c.tenant_id=t AND c.project_id=project AND c.state='open' AND v.body->>'responsible_id'=person::text\n$$"

ITEMS = "CREATE FUNCTION public.project_handover_items(t uuid, project uuid, person uuid)\n RETURNS TABLE(kind text, subject_id uuid, task_id uuid, label text, state text)\n LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\n SELECT i.* FROM project_handover_items_of(t, project, person) i\n WHERE t=nullif(current_setting('pdos.tenant_id',true),'')::uuid AND scope_actor()=scope_requester()\n  AND EXISTS(SELECT 1 FROM principals x WHERE x.tenant_id=t AND x.id=scope_requester() AND x.active AND x.kind='human')\n  AND (scope_requester()=person OR EXISTS(SELECT 1 FROM projects p WHERE p.tenant_id=t AND p.id=project\n   AND p.owner_id=scope_requester()))\n$$"

PERSON_OPEN = "CREATE FUNCTION public.project_person_open(t uuid, project uuid, person uuid) RETURNS boolean\n LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\n SELECT EXISTS(SELECT 1 FROM projects p WHERE p.tenant_id=t AND p.id=project\n  AND (p.visibility='category' OR p.owner_id=person OR EXISTS(SELECT 1 FROM object_audiences a\n   WHERE a.tenant_id=p.tenant_id AND a.category_id=p.category_id AND a.object_type='projects'\n    AND a.subject_id=p.id AND a.owner_id=p.owner_id AND a.principal_id=person)))\n$$"

HANDOVER_ONLY = "CREATE FUNCTION public.project_handover_only(t uuid, project uuid, person uuid) RETURNS boolean\n LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\n SELECT EXISTS(SELECT 1 FROM project_members m WHERE m.tenant_id=t AND m.project_id=project\n   AND m.principal_id=person AND m.handover_pending)\n  AND NOT EXISTS(SELECT 1 FROM project_members m WHERE m.tenant_id=t AND m.project_id=project\n   AND m.principal_id=person AND m.left_at IS NULL)\n  AND EXISTS(SELECT 1 FROM principals x WHERE x.tenant_id=t AND x.id=person AND x.active AND x.kind='human')\n$$"

LANE = "CREATE FUNCTION public.project_handover_lane(t uuid, project uuid) RETURNS boolean\n LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\n SELECT t=nullif(current_setting('pdos.tenant_id',true),'')::uuid AND scope_actor()=scope_requester()\n  AND project::text=ANY(string_to_array(nullif(current_setting('pdos.handover_lane',true),''),','))\n  AND project_handover_only(t, project, scope_requester())\n  AND EXISTS(SELECT 1 FROM project_handover_items_of(t, project, scope_requester()))\n$$"

SUBJECT = "CREATE FUNCTION public.project_handover_subject(t uuid, project uuid, subject_kind text, subject uuid) RETURNS boolean\n LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\n SELECT subject_kind IS NOT NULL AND project_handover_lane(t, project)\n  AND EXISTS(SELECT 1 FROM project_handover_items_of(t, project, scope_requester()) i WHERE (($3='work_task' AND i.kind IN ('work_task','work_commitment') AND i.task_id=$4)\n   OR ($3='external_wait' AND i.kind='external_wait' AND i.subject_id=$4)\n   OR $3 IS NULL))\n$$"

OPEN_LANE = "CREATE FUNCTION public.open_handover_lane(t uuid, project uuid, subject_kind text, subject uuid) RETURNS boolean\n LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\nBEGIN\n -- Only says whether the lane may open; the caller sets pdos.handover_lane itself,\n -- because a SECURITY DEFINER function's own SET LOCAL ends with the function.\n -- project_handover_lane re-checks all of this on every row.\n IF t IS DISTINCT FROM nullif(current_setting('pdos.tenant_id',true),'')::uuid OR scope_actor() IS DISTINCT FROM scope_requester()\n  OR NOT project_handover_only(t, project, scope_requester())\n  OR NOT EXISTS(SELECT 1 FROM project_handover_items_of(t, project, scope_requester()) i WHERE (($3='work_task' AND i.kind IN ('work_task','work_commitment') AND i.task_id=$4)\n   OR ($3='external_wait' AND i.kind='external_wait' AND i.subject_id=$4)\n   OR $3 IS NULL)) THEN\n  RETURN false;\n END IF;\n RETURN true;\nEND $$"

SETTLE = "CREATE FUNCTION public.settle_project_handover(t uuid, project uuid) RETURNS integer\n LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\nDECLARE m project_members; p projects; c project_member_audiences; heir uuid; settled integer := 0;\nBEGIN\n IF t IS DISTINCT FROM nullif(current_setting('pdos.tenant_id',true),'')::uuid OR NOT EXISTS(SELECT 1 FROM principals x WHERE x.tenant_id=t\n   AND x.id=scope_actor() AND x.active) THEN\n  RAISE EXCEPTION 'Handover settlement outside its tenant' USING ERRCODE='23514'; END IF;\n SELECT * INTO p FROM projects WHERE tenant_id=t AND id=project;\n IF NOT FOUND THEN RETURN 0; END IF;\n FOR m IN SELECT * FROM project_members x WHERE x.tenant_id=t AND x.project_id=project AND x.handover_pending\n   ORDER BY x.id FOR UPDATE LOOP\n  -- Deterministic rule (P56-2): settled once nothing of theirs is left to hand over.\n  CONTINUE WHEN EXISTS(SELECT 1 FROM project_handover_items_of(t, project, m.principal_id));\n  UPDATE project_members SET handover_pending=false WHERE id=m.id;\n  IF NOT EXISTS(SELECT 1 FROM project_members x WHERE x.tenant_id=t AND x.project_id=project\n    AND x.principal_id=m.principal_id AND x.left_at IS NULL) THEN\n   DELETE FROM object_audiences a WHERE a.tenant_id=t AND a.category_id=p.category_id AND a.object_type='projects'\n    AND a.subject_id=p.id AND a.owner_id=p.owner_id AND a.principal_id=m.principal_id;\n  END IF;\n  -- Upstream model/definition audiences: the same release rule as release_project_member_upstream.\n  FOR c IN SELECT * FROM project_member_audiences WHERE tenant_id=t AND member_id=m.id AND released_at IS NULL\n    ORDER BY id FOR UPDATE LOOP\n   UPDATE project_member_audiences SET released_at=statement_timestamp() WHERE id=c.id;\n   IF c.inserted THEN\n    heir := NULL;\n    SELECT o.id INTO heir FROM project_member_audiences o JOIN project_members x ON x.tenant_id=o.tenant_id AND x.id=o.member_id\n     WHERE o.tenant_id=t AND o.object_type=c.object_type AND o.subject_id=c.subject_id AND o.principal_id=c.principal_id\n      AND o.released_at IS NULL AND (x.left_at IS NULL OR x.handover_pending)\n     ORDER BY o.created_at, o.id LIMIT 1;\n    IF heir IS NOT NULL THEN\n     UPDATE project_member_audiences SET inserted=true WHERE id=heir;\n    ELSE\n     DELETE FROM object_audiences a WHERE a.tenant_id=t AND a.category_id=p.category_id AND a.object_type=c.object_type\n      AND a.subject_id=c.subject_id AND a.owner_id=c.owner_id AND a.principal_id=c.principal_id;\n    END IF;\n   END IF;\n  END LOOP;\n  settled := settled + 1;\n END LOOP;\n RETURN settled;\nEND $$"

DATA_UP = "DELETE FROM object_audiences a USING projects p\n WHERE a.tenant_id=p.tenant_id AND a.category_id=p.category_id AND a.object_type='projects'\n  AND a.subject_id=p.id AND a.owner_id=p.owner_id AND a.principal_id<>p.owner_id\n  AND EXISTS(SELECT 1 FROM project_members m WHERE m.tenant_id=p.tenant_id AND m.project_id=p.id\n   AND m.principal_id=a.principal_id AND m.handover_pending)\n  AND NOT EXISTS(SELECT 1 FROM project_members m WHERE m.tenant_id=p.tenant_id AND m.project_id=p.id\n   AND m.principal_id=a.principal_id AND m.left_at IS NULL)"

DATA_DOWN = "INSERT INTO object_audiences(id, tenant_id, created_at, category_id, object_type, subject_id, owner_id, principal_id)\n SELECT gen_random_uuid(), p.tenant_id, statement_timestamp(), p.category_id, 'projects', p.id, p.owner_id, m.principal_id\n FROM project_members m JOIN projects p ON p.tenant_id=m.tenant_id AND p.id=m.project_id\n WHERE m.handover_pending AND NOT EXISTS(SELECT 1 FROM project_members x WHERE x.tenant_id=m.tenant_id\n   AND x.project_id=m.project_id AND x.principal_id=m.principal_id AND x.left_at IS NULL)\n ON CONFLICT DO NOTHING"

MY_HANDOVER = "CREATE FUNCTION public.my_handover_projects(t uuid)\n RETURNS TABLE(project_id uuid, category_id uuid, product_id uuid, project_name text, owner_id uuid, left_at timestamptz)\n LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\n SELECT p.id, p.category_id, p.product_id, p.name, p.owner_id, max(m.left_at)\n FROM project_members m JOIN projects p ON p.tenant_id=m.tenant_id AND p.id=m.project_id\n WHERE t=nullif(current_setting('pdos.tenant_id',true),'')::uuid AND m.tenant_id=t AND m.principal_id=scope_requester()\n  AND m.handover_pending AND scope_actor()=scope_requester()\n  AND project_handover_only(t, p.id, scope_requester())\n  AND EXISTS(SELECT 1 FROM grants g WHERE g.tenant_id=t AND g.category_id=p.category_id AND g.principal_id=scope_requester()\n   AND (g.expires_at IS NULL OR g.expires_at>statement_timestamp()))\n  AND EXISTS(SELECT 1 FROM project_handover_items_of(t, p.id, scope_requester()))\n GROUP BY p.id, p.category_id, p.product_id, p.name, p.owner_id\n$$"

GUARD = "CREATE OR REPLACE FUNCTION public.guard_project_member()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE change project_team_changes; project projects;\nBEGIN\n IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Project member history is append only' USING ERRCODE='23514'; END IF;\n SELECT * INTO project FROM projects WHERE id=NEW.project_id AND tenant_id=NEW.tenant_id;\n IF NOT FOUND THEN RAISE EXCEPTION 'Project member outside its project' USING ERRCODE='23514'; END IF;\n IF TG_OP='INSERT' THEN\n  SELECT * INTO STRICT change FROM project_team_changes WHERE tenant_id=NEW.tenant_id AND project_id=NEW.project_id AND id=NEW.joined_change_id;\n  IF NEW.added_by IS DISTINCT FROM change.author_id OR NEW.left_at IS NOT NULL OR NEW.handover_pending THEN\n   RAISE EXCEPTION 'Invalid project member join' USING ERRCODE='23514'; END IF;\n  IF NOT EXISTS(SELECT 1 FROM principals p WHERE p.tenant_id=NEW.tenant_id AND p.id=NEW.principal_id AND p.active AND p.kind='human') THEN\n   RAISE EXCEPTION 'Project member must be an active named person' USING ERRCODE='23514'; END IF;\n  IF change.source<>'backfill' THEN\n   IF NOT EXISTS(SELECT 1 FROM grants g WHERE g.tenant_id=NEW.tenant_id AND g.category_id=project.category_id\n     AND g.principal_id=NEW.principal_id AND (g.expires_at IS NULL OR g.expires_at>statement_timestamp())) THEN\n    RAISE EXCEPTION 'Project member needs a category grant' USING ERRCODE='23514'; END IF;\n   NEW.joined_at=statement_timestamp();\n  END IF;\n  RETURN NEW;\n END IF;\n IF OLD.left_at IS NOT NULL THEN\n  -- Completing a removal kept open for handover (P56): only the flag clears, and only\n  -- once nothing of this person's is left to hand over, whoever closed the last item.\n  IF NOT OLD.handover_pending OR NEW.handover_pending\n   OR EXISTS(SELECT 1 FROM project_handover_items_of(NEW.tenant_id,NEW.project_id,NEW.principal_id))\n   OR ROW(NEW.id,NEW.tenant_id,NEW.created_at,NEW.project_id,NEW.principal_id,NEW.joined_at,NEW.added_by,NEW.joined_change_id,NEW.left_at,NEW.removed_by,NEW.left_change_id,NEW.departed_roles)\n    IS DISTINCT FROM ROW(OLD.id,OLD.tenant_id,OLD.created_at,OLD.project_id,OLD.principal_id,OLD.joined_at,OLD.added_by,OLD.joined_change_id,OLD.left_at,OLD.removed_by,OLD.left_change_id,OLD.departed_roles) THEN\n   RAISE EXCEPTION 'Invalid project member handover completion' USING ERRCODE='23514'; END IF;\n  RETURN NEW;\n END IF;\n IF NEW.left_at IS NULL OR (NEW.handover_pending AND project.visibility='category')\n  OR ROW(NEW.id,NEW.tenant_id,NEW.created_at,NEW.project_id,NEW.principal_id,NEW.joined_at,NEW.added_by,NEW.joined_change_id)\n   IS DISTINCT FROM ROW(OLD.id,OLD.tenant_id,OLD.created_at,OLD.project_id,OLD.principal_id,OLD.joined_at,OLD.added_by,OLD.joined_change_id)\n  OR NEW.removed_by IS DISTINCT FROM scope_actor() THEN\n  RAISE EXCEPTION 'Invalid project member leave' USING ERRCODE='23514'; END IF;\n IF NEW.principal_id=project.owner_id THEN\n  RAISE EXCEPTION 'Project owner stays on the team' USING ERRCODE='23514'; END IF;\n IF NOT EXISTS(SELECT 1 FROM project_team_changes c WHERE c.tenant_id=NEW.tenant_id AND c.project_id=NEW.project_id\n   AND c.id=NEW.left_change_id AND c.author_id=scope_actor() AND c.source='owner') THEN\n  RAISE EXCEPTION 'Invalid project member leave' USING ERRCODE='23514'; END IF;\n IF EXISTS(SELECT 1 FROM project_member_roles r WHERE r.tenant_id=NEW.tenant_id AND r.member_id=NEW.id) THEN\n  RAISE EXCEPTION 'Leaving member still holds roles' USING ERRCODE='23514'; END IF;\n NEW.left_at=greatest(statement_timestamp(),OLD.joined_at);\n RETURN NEW;\nEND $function$\n"

AUDIENCE = "CREATE OR REPLACE FUNCTION public.require_project_team_audience()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE row_value jsonb; t uuid; pid uuid; owner uuid;\nBEGIN\n IF TG_OP='DELETE' THEN row_value=to_jsonb(OLD); ELSE row_value=to_jsonb(NEW); END IF;\n IF TG_TABLE_NAME='object_audiences' THEN\n  IF row_value->>'object_type'<>'projects' THEN RETURN NULL; END IF;\n  pid=(row_value->>'subject_id')::uuid;\n ELSE\n  pid=(row_value->>'project_id')::uuid;\n END IF;\n t=(row_value->>'tenant_id')::uuid;\n SELECT p.owner_id INTO owner FROM projects p WHERE p.tenant_id=t AND p.id=pid;\n IF NOT FOUND THEN RETURN NULL; END IF;\n IF EXISTS(\n   (SELECT a.principal_id FROM object_audiences a WHERE a.tenant_id=t AND a.object_type='projects'\n     AND a.subject_id=pid AND a.owner_id=owner\n    EXCEPT SELECT m.principal_id FROM project_members m WHERE m.tenant_id=t AND m.project_id=pid AND m.left_at IS NULL)\n   UNION ALL\n   (SELECT m.principal_id FROM project_members m WHERE m.tenant_id=t AND m.project_id=pid AND m.left_at IS NULL\n    EXCEPT SELECT a.principal_id FROM object_audiences a WHERE a.tenant_id=t AND a.object_type='projects'\n     AND a.subject_id=pid AND a.owner_id=owner)) THEN\n  RAISE EXCEPTION 'Project audience differs from its current members' USING ERRCODE='23514';\n END IF;\n RETURN NULL;\nEND $function$\n"

RELEASABLE = "CREATE OR REPLACE FUNCTION public.project_audience_releasable(t uuid, project uuid, person uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\n SELECT EXISTS(SELECT 1 FROM projects p WHERE p.tenant_id=t AND p.id=project AND p.owner_id=scope_actor()\n   AND p.owner_id<>person AND scope_actor()=scope_requester())\n  AND EXISTS(SELECT 1 FROM project_members m WHERE m.tenant_id=t AND m.project_id=project AND m.principal_id=person)\n  AND NOT EXISTS(SELECT 1 FROM project_members m WHERE m.tenant_id=t AND m.project_id=project AND m.principal_id=person\n   AND m.left_at IS NULL)\n$function$\n"

RECEIPT = "CREATE OR REPLACE FUNCTION public.work_receipt_project_visible(t uuid, c uuid, p uuid, kind text, target uuid, rev integer, receipt uuid, actor uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE STRICT SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE project_id uuid; project_owner uuid; project_visibility text; actual_project public.projects;\nBEGIN\n IF NOT public.category_access(t,c) THEN RETURN false; END IF;\n IF kind='work_task' THEN\n  SELECT x.project_id,x.owner_id,x.visibility INTO project_id,project_owner,project_visibility\n   FROM public.work_task_versions x WHERE x.tenant_id=t AND x.category_id=c AND x.product_id=p AND x.id=target AND x.revision=rev AND x.receipt_id=receipt AND x.actor_id=actor;\n ELSIF kind='work_commitment' THEN\n  SELECT x.project_id,x.owner_id,x.visibility INTO project_id,project_owner,project_visibility\n   FROM public.work_commitment_versions x WHERE x.tenant_id=t AND x.category_id=c AND x.product_id=p AND x.id=target AND x.revision=rev AND x.receipt_id=receipt AND x.actor_id=actor;\n ELSIF kind='project_status_update' THEN\n  SELECT x.project_id,x.owner_id,x.visibility INTO project_id,project_owner,project_visibility\n   FROM public.project_status_updates x WHERE x.tenant_id=t AND x.category_id=c AND x.product_id=p AND x.id=target AND x.revision=rev AND x.receipt_id=receipt AND x.actor_id=actor;\n ELSIF kind='work_commitment_review' THEN\n  SELECT x.project_id,x.owner_id,x.visibility INTO project_id,project_owner,project_visibility\n   FROM public.work_commitment_reviews x WHERE x.tenant_id=t AND x.category_id=c AND x.product_id=p AND x.id=target AND x.revision=rev AND x.receipt_id=receipt AND x.actor_id=actor;\n ELSIF kind='external_wait' THEN\n  SELECT x.project_id,x.owner_id,x.visibility INTO project_id,project_owner,project_visibility FROM public.external_wait_versions x WHERE x.tenant_id=t AND x.category_id=c AND x.product_id=p AND x.id=target AND x.revision=rev AND x.receipt_id=receipt AND x.actor_id=actor;\n ELSIF kind='risk_followup' THEN\n  SELECT x.project_id,x.owner_id,x.visibility INTO project_id,project_owner,project_visibility FROM public.project_risk_followups x WHERE x.tenant_id=t AND x.category_id=c AND x.product_id=p AND x.id=target AND x.revision=rev AND x.receipt_id=receipt AND x.actor_id=actor;\n ELSE RETURN false; END IF;\n IF project_id IS NULL THEN RETURN false; END IF;\n SELECT * INTO actual_project FROM public.projects x WHERE x.tenant_id=t AND x.category_id=c AND x.product_id=p AND x.id=project_id AND x.owner_id=project_owner AND x.visibility=project_visibility;\n RETURN actual_project.id IS NOT NULL AND (actual_project.visibility='category' OR actual_project.owner_id=public.scope_requester() OR EXISTS(\n  SELECT 1 FROM public.object_audiences a WHERE a.tenant_id=t AND a.category_id=c AND a.object_type='projects'\n   AND a.subject_id=actual_project.id AND a.owner_id=actual_project.owner_id AND a.principal_id=public.scope_requester())\n  OR public.project_handover_lane(t,actual_project.id));\nEND;\n$function$\n"

SOURCE_AUDIENCE = "CREATE OR REPLACE FUNCTION public.source_object_audience(t uuid, c uuid, typ text, sid uuid, own uuid, vis text)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\n SELECT category_access(t,c,false) AND (\n   vis='category' OR own=scope_requester() OR EXISTS (\n     SELECT 1 FROM object_audiences a\n     WHERE a.tenant_id=t AND a.category_id=c AND a.object_type=typ\n       AND a.subject_id=sid AND a.owner_id=own AND a.principal_id=scope_requester()\n   )\n   -- P56 handover lane: a removed member's own open item, in this transaction only.\n   OR (typ='projects' AND coalesce(current_setting('pdos.handover_lane',true),'')<>''\n    AND project_handover_lane(t, sid))\n )\n$function$\n"

OLD_SOURCE_AUDIENCE = "CREATE OR REPLACE FUNCTION public.source_object_audience(t uuid, c uuid, typ text, sid uuid, own uuid, vis text)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\n SELECT category_access(t,c,false) AND (\n   vis='category' OR own=scope_requester() OR EXISTS (\n     SELECT 1 FROM object_audiences a\n     WHERE a.tenant_id=t AND a.category_id=c AND a.object_type=typ\n       AND a.subject_id=sid AND a.owner_id=own AND a.principal_id=scope_requester()\n   )\n )\n$function$\n"

POLICY_UP = "ALTER POLICY category_scope ON public.projects USING (((category_access(tenant_id, category_id) AND (((visibility)::text = 'category'::text) OR (owner_id = scope_requester()) OR (EXISTS ( SELECT 1\n   FROM object_audiences a\n  WHERE ((a.tenant_id = projects.tenant_id) AND (a.category_id = projects.category_id) AND ((a.object_type)::text = 'projects'::text) AND (a.subject_id = projects.id) AND (a.owner_id = projects.owner_id) AND (a.principal_id = scope_requester()))))))) OR (coalesce(current_setting('pdos.handover_lane',true),'')<>'' AND category_access(tenant_id, category_id) AND public.project_handover_lane(tenant_id, id)))"

POLICY_DOWN = "ALTER POLICY category_scope ON public.projects USING ((category_access(tenant_id, category_id) AND (((visibility)::text = 'category'::text) OR (owner_id = scope_requester()) OR (EXISTS ( SELECT 1\n   FROM object_audiences a\n  WHERE ((a.tenant_id = projects.tenant_id) AND (a.category_id = projects.category_id) AND ((a.object_type)::text = 'projects'::text) AND (a.subject_id = projects.id) AND (a.owner_id = projects.owner_id) AND (a.principal_id = scope_requester())))))))"

OLD_GUARD = "CREATE OR REPLACE FUNCTION public.guard_project_member()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE change project_team_changes; project projects;\nBEGIN\n IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Project member history is append only' USING ERRCODE='23514'; END IF;\n SELECT * INTO project FROM projects WHERE id=NEW.project_id AND tenant_id=NEW.tenant_id;\n IF NOT FOUND THEN RAISE EXCEPTION 'Project member outside its project' USING ERRCODE='23514'; END IF;\n IF TG_OP='INSERT' THEN\n  SELECT * INTO STRICT change FROM project_team_changes WHERE tenant_id=NEW.tenant_id AND project_id=NEW.project_id AND id=NEW.joined_change_id;\n  IF NEW.added_by IS DISTINCT FROM change.author_id OR NEW.left_at IS NOT NULL OR NEW.handover_pending THEN\n   RAISE EXCEPTION 'Invalid project member join' USING ERRCODE='23514'; END IF;\n  IF NOT EXISTS(SELECT 1 FROM principals p WHERE p.tenant_id=NEW.tenant_id AND p.id=NEW.principal_id AND p.active AND p.kind='human') THEN\n   RAISE EXCEPTION 'Project member must be an active named person' USING ERRCODE='23514'; END IF;\n  IF change.source<>'backfill' THEN\n   IF NOT EXISTS(SELECT 1 FROM grants g WHERE g.tenant_id=NEW.tenant_id AND g.category_id=project.category_id\n     AND g.principal_id=NEW.principal_id AND (g.expires_at IS NULL OR g.expires_at>statement_timestamp())) THEN\n    RAISE EXCEPTION 'Project member needs a category grant' USING ERRCODE='23514'; END IF;\n   NEW.joined_at=statement_timestamp();\n  END IF;\n  RETURN NEW;\n END IF;\n IF OLD.left_at IS NOT NULL THEN\n  -- Completing a removal kept open for handover: only the flag clears, by the owner.\n  IF NOT OLD.handover_pending OR NEW.handover_pending OR project.owner_id IS DISTINCT FROM scope_actor()\n   OR ROW(NEW.id,NEW.tenant_id,NEW.created_at,NEW.project_id,NEW.principal_id,NEW.joined_at,NEW.added_by,NEW.joined_change_id,NEW.left_at,NEW.removed_by,NEW.left_change_id,NEW.departed_roles)\n    IS DISTINCT FROM ROW(OLD.id,OLD.tenant_id,OLD.created_at,OLD.project_id,OLD.principal_id,OLD.joined_at,OLD.added_by,OLD.joined_change_id,OLD.left_at,OLD.removed_by,OLD.left_change_id,OLD.departed_roles) THEN\n   RAISE EXCEPTION 'Invalid project member handover completion' USING ERRCODE='23514'; END IF;\n  RETURN NEW;\n END IF;\n IF NEW.left_at IS NULL OR (NEW.handover_pending AND project.visibility='category')\n  OR ROW(NEW.id,NEW.tenant_id,NEW.created_at,NEW.project_id,NEW.principal_id,NEW.joined_at,NEW.added_by,NEW.joined_change_id)\n   IS DISTINCT FROM ROW(OLD.id,OLD.tenant_id,OLD.created_at,OLD.project_id,OLD.principal_id,OLD.joined_at,OLD.added_by,OLD.joined_change_id)\n  OR NEW.removed_by IS DISTINCT FROM scope_actor() THEN\n  RAISE EXCEPTION 'Invalid project member leave' USING ERRCODE='23514'; END IF;\n IF NEW.principal_id=project.owner_id THEN\n  RAISE EXCEPTION 'Project owner stays on the team' USING ERRCODE='23514'; END IF;\n IF NOT EXISTS(SELECT 1 FROM project_team_changes c WHERE c.tenant_id=NEW.tenant_id AND c.project_id=NEW.project_id\n   AND c.id=NEW.left_change_id AND c.author_id=scope_actor() AND c.source='owner') THEN\n  RAISE EXCEPTION 'Invalid project member leave' USING ERRCODE='23514'; END IF;\n IF EXISTS(SELECT 1 FROM project_member_roles r WHERE r.tenant_id=NEW.tenant_id AND r.member_id=NEW.id) THEN\n  RAISE EXCEPTION 'Leaving member still holds roles' USING ERRCODE='23514'; END IF;\n NEW.left_at=greatest(statement_timestamp(),OLD.joined_at);\n RETURN NEW;\nEND $function$\n"

OLD_AUDIENCE = "CREATE OR REPLACE FUNCTION public.require_project_team_audience()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE row_value jsonb; t uuid; pid uuid; owner uuid;\nBEGIN\n IF TG_OP='DELETE' THEN row_value=to_jsonb(OLD); ELSE row_value=to_jsonb(NEW); END IF;\n IF TG_TABLE_NAME='object_audiences' THEN\n  IF row_value->>'object_type'<>'projects' THEN RETURN NULL; END IF;\n  pid=(row_value->>'subject_id')::uuid;\n ELSE\n  pid=(row_value->>'project_id')::uuid;\n END IF;\n t=(row_value->>'tenant_id')::uuid;\n SELECT p.owner_id INTO owner FROM projects p WHERE p.tenant_id=t AND p.id=pid;\n IF NOT FOUND THEN RETURN NULL; END IF;\n IF EXISTS(\n   (SELECT a.principal_id FROM object_audiences a WHERE a.tenant_id=t AND a.object_type='projects'\n     AND a.subject_id=pid AND a.owner_id=owner\n    EXCEPT SELECT m.principal_id FROM project_members m WHERE m.tenant_id=t AND m.project_id=pid AND (m.left_at IS NULL OR m.handover_pending))\n   UNION ALL\n   (SELECT m.principal_id FROM project_members m WHERE m.tenant_id=t AND m.project_id=pid AND (m.left_at IS NULL OR m.handover_pending)\n    EXCEPT SELECT a.principal_id FROM object_audiences a WHERE a.tenant_id=t AND a.object_type='projects'\n     AND a.subject_id=pid AND a.owner_id=owner)) THEN\n  RAISE EXCEPTION 'Project audience differs from its current members' USING ERRCODE='23514';\n END IF;\n RETURN NULL;\nEND $function$\n"

OLD_RELEASABLE = "CREATE OR REPLACE FUNCTION public.project_audience_releasable(t uuid, project uuid, person uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\n SELECT EXISTS(SELECT 1 FROM projects p WHERE p.tenant_id=t AND p.id=project AND p.owner_id=scope_actor()\n   AND p.owner_id<>person AND scope_actor()=scope_requester())\n  AND EXISTS(SELECT 1 FROM project_members m WHERE m.tenant_id=t AND m.project_id=project AND m.principal_id=person)\n  AND NOT EXISTS(SELECT 1 FROM project_members m WHERE m.tenant_id=t AND m.project_id=project AND m.principal_id=person\n   AND (m.left_at IS NULL OR m.handover_pending))\n$function$\n"

OLD_RECEIPT = "CREATE OR REPLACE FUNCTION public.work_receipt_project_visible(t uuid, c uuid, p uuid, kind text, target uuid, rev integer, receipt uuid, actor uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE STRICT SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE project_id uuid; project_owner uuid; project_visibility text; actual_project public.projects;\nBEGIN\n IF NOT public.category_access(t,c) THEN RETURN false; END IF;\n IF kind='work_task' THEN\n  SELECT x.project_id,x.owner_id,x.visibility INTO project_id,project_owner,project_visibility\n   FROM public.work_task_versions x WHERE x.tenant_id=t AND x.category_id=c AND x.product_id=p AND x.id=target AND x.revision=rev AND x.receipt_id=receipt AND x.actor_id=actor;\n ELSIF kind='work_commitment' THEN\n  SELECT x.project_id,x.owner_id,x.visibility INTO project_id,project_owner,project_visibility\n   FROM public.work_commitment_versions x WHERE x.tenant_id=t AND x.category_id=c AND x.product_id=p AND x.id=target AND x.revision=rev AND x.receipt_id=receipt AND x.actor_id=actor;\n ELSIF kind='project_status_update' THEN\n  SELECT x.project_id,x.owner_id,x.visibility INTO project_id,project_owner,project_visibility\n   FROM public.project_status_updates x WHERE x.tenant_id=t AND x.category_id=c AND x.product_id=p AND x.id=target AND x.revision=rev AND x.receipt_id=receipt AND x.actor_id=actor;\n ELSIF kind='work_commitment_review' THEN\n  SELECT x.project_id,x.owner_id,x.visibility INTO project_id,project_owner,project_visibility\n   FROM public.work_commitment_reviews x WHERE x.tenant_id=t AND x.category_id=c AND x.product_id=p AND x.id=target AND x.revision=rev AND x.receipt_id=receipt AND x.actor_id=actor;\n ELSIF kind='external_wait' THEN\n  SELECT x.project_id,x.owner_id,x.visibility INTO project_id,project_owner,project_visibility FROM public.external_wait_versions x WHERE x.tenant_id=t AND x.category_id=c AND x.product_id=p AND x.id=target AND x.revision=rev AND x.receipt_id=receipt AND x.actor_id=actor;\n ELSIF kind='risk_followup' THEN\n  SELECT x.project_id,x.owner_id,x.visibility INTO project_id,project_owner,project_visibility FROM public.project_risk_followups x WHERE x.tenant_id=t AND x.category_id=c AND x.product_id=p AND x.id=target AND x.revision=rev AND x.receipt_id=receipt AND x.actor_id=actor;\n ELSE RETURN false; END IF;\n IF project_id IS NULL THEN RETURN false; END IF;\n SELECT * INTO actual_project FROM public.projects x WHERE x.tenant_id=t AND x.category_id=c AND x.product_id=p AND x.id=project_id AND x.owner_id=project_owner AND x.visibility=project_visibility;\n RETURN actual_project.id IS NOT NULL AND (actual_project.visibility='category' OR actual_project.owner_id=public.scope_requester() OR EXISTS(\n  SELECT 1 FROM public.object_audiences a WHERE a.tenant_id=t AND a.category_id=c AND a.object_type='projects'\n   AND a.subject_id=actual_project.id AND a.owner_id=actual_project.owner_id AND a.principal_id=public.scope_requester()));\nEND;\n$function$\n"

